    def _serve(self, conn: socket.socket) -> None:
        reader = LineReader()
        try:
            # First line from the client is treated as the desired nickname.
            nickname_set = False
            while self._running.is_set():
                data = conn.recv(4096)
                if not data:
                    break
                for line in reader.feed(data):
                    if not nickname_set:
                        # Process nickname selection
                        desired = line.strip()
                        if not desired:
                            # Empty nickname not allowed; ask again.
                            conn.sendall(encode("Nickname cannot be empty"))
                            continue
                        with self._lock:
                            if desired in self._clients.values():
                                # Nickname already taken
                                conn.sendall(encode("Nickname already taken"))
                                # Close connection after notifying client
                                self._remove(conn)
                                return
                            # Set the nickname for this connection
                            self._clients[conn] = desired
                        nickname_set = True
                        # Optionally announce the new user
                        self.broadcast(f"{desired} has joined the chat", sender=conn)
                    else:
                        if line.strip():
                            self.broadcast(f"{self._name(conn)}: {line}", sender=conn)
        except (OSError, ValueError):
            pass
        finally:
            self._remove(conn)
